import{_ as a,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"29、【坎】 坎下坎上","description":"周易阐真 - 29、【坎】 坎下坎上","frontmatter":{"title":"29、【坎】 坎下坎上","description":"周易阐真 - 29、【坎】 坎下坎上"},"headers":[],"relativePath":"zh/classics/chanzhen/030.md","filePath":"zh/classics/chanzhen/030.md"}'),s={name:"zh/classics/chanzhen/030.md"};function n(c,p,i,o,h,l){return t(),e("div",null,[...p[0]||(p[0]=[r('<blockquote><p>彖曰：习坎，重险也。水流而不盈。行险而不失其信。维心亨，乃以刚中也。行有尚，往有功也。天险，不可升也。地险，山川丘陵也。王公设险以守其国。险之时用大矣哉！</p></blockquote><h1 id="_29、【坎】-坎下坎上" tabindex="-1">29、【坎】 坎下坎上 <a class="header-anchor" href="#_29、【坎】-坎下坎上" aria-label="Permalink to “29、【坎】 坎下坎上”">​</a></h1><p>初六：习坎，入于坎窞，凶。</p><p>九二：坎有险，求小得。</p><p>六三：来之坎坎，险且枕。入于坎窞，勿用。</p><p>六四：樽酒簋贰。用缶纳约，自牖终无咎。</p><p>九五：坎不盈，祗既平，无咎。</p><p>上六：系用徽墨副本，寘于丛棘，三岁不得，凶。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：水洊至，习坎。君子以常德行，习教事。</p><p>洊音荐。</p><p>习坎者，水由此达彼也。上坎水，下坎水，是水由此而洊至于彼，由彼而洊至于此，洊而流通，习坎之象也。</p><p>君子有见于此，知圣贤之事，乃成己成物两端。成己者，德行也；成物者，教事也。德行不常，则大道难入；教事不习，则学人不悟。以是于德行日就月将，温故知新，愈久愈力，期必至于深造自得而后已；于教事渐次开导，明提暗点，愈入愈引，期必至于学人通彻无疑而后已。盖德行者，身心性命之学，最精最细，毫发之差，千里之失；惟常之，则穷理尽性至命，而己可成矣。教事者，承先启后之事，至切至要，讲论不明，误人前程；惟习之，则探赜索隐阐幽，而物可成矣。但教事本于德行，教事即教其德行之事。能常德行，方能习教事；若不能常德行，则教事无本。先常德行，而后习教事，常于己者如是，习于人者亦如是，犹之水洊由此达彼，总是一水，无处不可流通也。</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>窞，音陷。枕，音正。簋，音轨。祗，音支。墨副本，音墨。寘，音置。棘，音吉。</p><p>坎者，险也，陷也。习坎者，通险也。卦德上坎险、下坎险，由此险而达彼险，险而能通，故谓习坎。此黑中有白，阴中返阳之卦，承上颐卦而来。颐者，以虚求实，求其坎陷之真阳也。</p><p>人自乾坤相交之后，一点元阳，走于坤宫，坤实而成坎，乾变而成离，于是阴陷其阳，天根昧而心交物，性相近而习相远，日习日下，陷于下愚不移之地，而莫知底止矣。</p><p>然习恶则恶，习善则善，是在人习之如何耳。习恶者，入险之道；习善者，出险之道。出险须要能信其险。信者，心之主宰，若能信险，则不为外物所惑，习于善而即能善，所谓一念回机，如同本得，是以习坎有孚，维心亨也。</p><p>有孚即心亨，不孚心不亨。有孚之心，即是道心，道心发现，人心不起，正气增长，邪气渐退，可以出入乎阴阳之中，而不为阴阳所拘矣。但信其有险，须要习而出险，信而不习，如不信也。既能信又能习，不隐不瞒，真履实践，日习日善，自卑登高，由下而上，渐习于高明之境，尽性至命，还元复初而无难，故曰“行有尚”。尚者，上也。行之能上，不行不上，知之尤贵于行之耳。</p><p>初六，性质本愚，又习于愚，日习日下，是谓习坎。在下之习，如在坎坑，又钻窞孔，入于下流之处，而莫知所止，不凶而自致凶。此愚而又习于愚者也。</p><p>九二，居于二阴之中，日与小人为伍，不知亲近有道之士，终陷于下而为愚人，如在坎坑之中而有险也。幸其刚而得中，陷之不深，虽不能出险，内有主宰，亦不为下流所惑。但嫌其信险而不习出险，仅小有得，不能明善复初，大有得耳。此刚而不知习善者也。</p><p>六三，性质本险，又愚而自用以行险，险而又险，是来之坎坎矣。且近上险，前进上险，后退亦险，是险且枕矣。如此之人，不信有险，愈习愈险，习之者久，陷之者深，如入于坎窞，终在险地，永为物用之人矣。此柔而只知习恶者也。</p><p>六四，在上刚下柔之际，性质在中人之列，习于善则能善，习于恶则即恶，可善可恶，如一樽酒而用二簋盛之也。然四与五同居，信于善者，信于善而虚心下贤，借他人之明智，以破己之昏暗，如用缶纳约，自牖以通其明。不能善者亦能善，始有咎者，终可无咎。此柔而能习其善者也。</p><p>九五，居二阴之间，阳刚中正，把柄在手，既能不满不盈，不见恶于小人，又能不迁不流，大有异于小人，如坎水不盈，祗既平。不满于内，亦不流外，实腹而能虚心，出于性成，是以无咎。此上智不移、不待习而自善者也。</p><p>上六，虽系小人，本性未尝不善，但性善而不知习善，自缚自束。系于不善，自暴自弃，居于险地，如系用徽墨副本，寘于丛棘，终亦必亡而已。岂仅三岁不得出险哉!此下愚不移、终不习而终恶者也。</p><p>然则修道者，当自醒自悟，急须拜求真师，寻个出头之路，以了性命，甚勿以福缘浅薄、自暴自弃，为世间无用之物。</p><p>盖身心性命之学，人人有份。回头是岸，立登圣基，是在人之能信能习耳。果能信之习之，日习日善，必将习于至善无恶，浑然天理地位矣。人何乐而不习善哉!</p>',27)])])}const m=a(s,[["render",n]]);export{d as __pageData,m as default};
